import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Card, Flex, theme, Tooltip, Typography } from 'antd';
import cn from 'classnames';

import CrossSellIcon from 'assets/images/catalog/cross-sell.svg?react';
import { IBrand, useJoinBrand } from 'entities/Brand';
import { OfferCard } from 'entities/Offer';
import { useMedia } from 'shared/hooks';
import { BrandAccordion, CatalogLabel } from 'shared/ui';
import { getNoun } from 'shared/utils';

import styles from './BrandCard.module.scss';

interface IBrandCardProps extends HTMLAttributes<HTMLDivElement> {
	brand: IBrand;
	allIsOpened?: boolean;
}

export const BrandCard: FC<IBrandCardProps> = ({ className, brand, allIsOpened, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const {
		token: { colorPrimaryBg, colorPrimary },
	} = theme.useToken();
	const [isOpen, setIsOpen] = useState(!!allIsOpened);

	useEffect(() => {
		setIsOpen(!!allIsOpened);
	}, [allIsOpened]);

	const { joinIsDisabled, onJoin } = useJoinBrand(brand);

	const hasCrossSell =
		!!brand?.cross_sell_rates &&
		(brand.cross_sell_rates.fixed_payout_size || brand.cross_sell_rates.percent_payout_sizes);

	return (
		<Card {...props} className={cn(className, styles.card)} styles={{ body: { padding: 0 } }}>
			<Flex
				vertical={isMd}
				align={isMd ? 'stretch' : 'center'}
				justify="space-between"
				gap={16}
				className={styles.main}>
				<Flex align="center" gap={16}>
					<img src={brand.image} alt={brand.name} width={80} />
					<Typography.Text strong>{brand.name}</Typography.Text>
				</Flex>

				<Flex vertical={isMd} align={isMd ? 'flex-start' : 'center'} gap={16}>
					{hasCrossSell && (
						<CatalogLabel
							color={colorPrimary}
							Icon={CrossSellIcon}
							backgroundColor={colorPrimaryBg}
							value={`До ${brand.cross_sell_rates?.fixed_payout_size || brand.cross_sell_rates?.percent_payout_sizes}`}
							tooltip={t(
								'Оплата всех целевых действий в рамках одного бренда без привязки к ссылке перехода (оффера).',
							)}
						/>
					)}
					<Tooltip
						title={
							joinIsDisabled
								? t(
										'Вы подали заявку/заявки на все ваши площадки. Чтобы снова подать заявку вам нужно добавить новую площадку.',
									)
								: t('Нажимая на эту кнопку вы подаете заявку на подключение ко всем офферам внутри бренда')
						}>
						<Button
							type="primary"
							size="small"
							onClick={() => onJoin()}
							style={{ padding: '0 21px' }}
							disabled={joinIsDisabled}
							block={isMd}>
							{t('Подключиться к бренду')}
						</Button>
					</Tooltip>
				</Flex>
			</Flex>

			<BrandAccordion
				isOpen={isOpen}
				setIsOpen={setIsOpen}
				buttonText={`${t('Показать {{count}} ', { count: brand.offers.length })} ${getNoun(brand.offers.length, [t('оффер'), t('оффера'), t('офферов')])}`}>
				{brand.offers.map((offer) => (
					<OfferCard key={offer.uuid} offer={offer} brand={brand} />
				))}
			</BrandAccordion>
		</Card>
	);
};
