import { IBrand, useBrandsSlice } from 'entities/Brand';
import { useMeta } from 'shared/hooks';
import { EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

export const useJoinBrand = (brand?: IBrand) => {
	const { setJoinedBrand, setOpenedModal } = useBrandsSlice();
	const { sourcesCount, activeSourcesCount, userCanJoinToOffer } = useMeta();

	if (!brand) {
		return {
			joinIsDisabled: true,
			onJoin: () => {},
		};
	}

	const canJoin = brand.offers.some(({ sources_relations }) => userCanJoinToOffer(sources_relations));

	const joinIsDisabled = !canJoin && activeSourcesCount > 0;

	const onJoin = (o2?: EYmEventsO2, o4?: string) => {
		sendYmEvent({
			event: EYmEvents.CLICK_JOIN,
			o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
			o2: o2 || EYmEventsO2.CATALOG,
			pi: brand.uuid,
			o4,
		});

		if (sourcesCount === 0) {
			setOpenedModal('no_source');
		} else if (activeSourcesCount === 0) {
			setOpenedModal('no_active_source');
		} else {
			setJoinedBrand(brand);
		}
	};

	return {
		joinIsDisabled,
		onJoin,
	};
};
