import { FC, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, FlexProps } from 'antd';

import { BrandCard, useGetBrandsListQuery } from 'entities/Brand';
import { BrandsFilters, EFilters, useFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { Sort } from 'features/Sort';
import { EmptyState, ListTopbar, OpenAllSwitch, OverlayLoader } from 'shared/ui';
import { SORT_ITEMS } from 'widgets/BrandsList';

interface IBrandsListProps extends FlexProps {}

export const BrandsList: FC<Omit<IBrandsListProps, 'children'>> = ({ ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue } = useFilters();
	const [allIsOpened, setAllIsOpened] = useState(
		!!getFilterValue(EFilters.BRAND) || !!localStorage.getItem('allIsOpened'),
	);

	const [searchParams] = useSearchParams();
	const { data, isFetching } = useGetBrandsListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;

	return (
		<Flex {...props} vertical gap={16}>
			{isFetching && <OverlayLoader />}

			<BrandsFilters />

			{!hasData && !isFetching && <EmptyState title={t('Пока нет предложений')} />}

			{hasData && (
				<>
					<ListTopbar
						leftComponent={<Sort sortItems={SORT_ITEMS} />}
						rightComponent={<OpenAllSwitch allIsOpened={allIsOpened} setAllIsOpened={setAllIsOpened} />}
					/>

					<Flex vertical gap={12}>
						{data.results?.map((brand) => <BrandCard key={brand.uuid} brand={brand} allIsOpened={allIsOpened} />)}
					</Flex>

					<Pagination count={data?.count || 1} nouns={[t('рекламодатель'), t('рекламодателя'), t('рекламодателей')]} />
				</>
			)}
		</Flex>
	);
};
