import { HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, Select } from 'antd';
import cn from 'classnames';

import FiltersIcon from 'assets/images/icons/filters.svg?react';
import { ESourceRelationStatuses } from 'entities/Offer';
import { BrandExtendedFilters, EFilters, useFilters } from 'features/Filters';
import { useTrans } from 'shared/hooks';
import { EYmEvents, EYmEventsO1, EYmEventsO2, EYmEventsO4 } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import styles from './BrandsFilters.module.scss';

export interface IBrandsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const BrandsFilters = ({ className, ...props }: IBrandsFiltersProps) => {
	const { t } = useTranslation();
	const [filtersIsOpened, setFiltersIsOpened] = useState(false);
	const {
		sourcesOptions,
		brandsOptions,
		sourcesIsFetching,
		brandsIsFetching,
		getFiltersCount,
		onFilterChange,
		getALLFilterValues,
	} = useFilters();
	const { relationStatuses } = useTrans();

	return (
		<div {...props} className={cn(className, styles.filters)}>
			<Select
				size="small"
				mode="multiple"
				maxTagCount="responsive"
				onChange={(value) => onFilterChange(EFilters.SOURCE, value)}
				onSelect={(value) =>
					sendYmEvent({
						event: EYmEvents.CLICK_FILTER,
						o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
						o2: EYmEventsO2.FILTER,
						o4: EYmEventsO4.ADSPACE,
						wi: value,
						isMarketing: false,
					})
				}
				value={sourcesIsFetching ? null : getALLFilterValues(EFilters.SOURCE)}
				options={sourcesOptions}
				loading={sourcesIsFetching}
				disabled={sourcesIsFetching}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать площадку')}
				allowClear
			/>

			<Select
				size="small"
				mode="multiple"
				maxTagCount="responsive"
				onChange={(value) => onFilterChange(EFilters.BRAND, value)}
				onSelect={(value) =>
					sendYmEvent({
						event: EYmEvents.CLICK_FILTER,
						o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
						o2: EYmEventsO2.FILTER,
						o4: EYmEventsO4.ADVERTISER,
						pi: value,
						isMarketing: false,
					})
				}
				value={brandsIsFetching ? null : getALLFilterValues(EFilters.BRAND)}
				options={brandsOptions}
				loading={brandsIsFetching}
				disabled={brandsIsFetching}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать рекламодателя')}
				allowClear
			/>

			<Select
				size="small"
				mode="multiple"
				maxTagCount="responsive"
				onChange={(value) => onFilterChange(EFilters.STATUS, value)}
				value={getALLFilterValues(EFilters.STATUS)}
				options={Object.entries(relationStatuses)
					.filter(([key]) => key !== ESourceRelationStatuses.DISABLED && key !== ESourceRelationStatuses.NOT_JOINED)
					.map(([value, label]) => ({ label, value }))}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать статус')}
				allowClear
			/>

			<Button size="small" icon={<FiltersIcon />} onClick={() => setFiltersIsOpened(true)}>
				{t('Фильтры')} <Badge size="small" count={getFiltersCount()} />
			</Button>

			<BrandExtendedFilters open={filtersIsOpened} onClose={() => setFiltersIsOpened(false)} />
		</div>
	);
};

export default BrandsFilters;
