import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import cn from 'classnames';

import { useMedia } from 'shared/hooks';
import { EMainRoutes, EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { ButtonStyleLink, Page, PageTitle } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';
import { BrandsList } from 'widgets/BrandsList';
import { CatalogBanner } from 'widgets/CatalogBanner';

import styles from './Catalog.module.scss';

interface ICatalogProps extends HTMLAttributes<HTMLDivElement> {}

export const Catalog: FC<ICatalogProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();

	return (
		<Page {...props} className={cn(className, styles.catalog)}>
			<CatalogBanner />

			<PageTitle
				//subtitle={t('Здесь можно представить краткое описание раздела')}
				component={
					<ButtonStyleLink
						size="small"
						color="primary"
						variant="outlined"
						block={isMd}
						to={`/${EMainRoutes.SOURCES}/${EMainRoutes.CREATE}`}
						onClick={() => {
							sendYmEvent({
								event: EYmEvents.CLICK_ADD_ADSPACE,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.HEADER,
							});
						}}>
						+ {t('Добавить площадку')}
					</ButtonStyleLink>
				}>
				{t('Каталог')}
			</PageTitle>
			<BrandsList />
		</Page>
	);
};

export default Catalog;
