import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Checkbox, Drawer, DrawerProps, Flex, Form, Select } from 'antd';
import cn from 'classnames';

import { ESourceRelationStatuses } from 'entities/Offer';
import { EFilters, useFilters } from 'features/Filters';
import { useCommonSlice, useDisableBodyScroll } from 'shared/hooks';
import { EYmEvents, EYmEventsO1, EYmEventsO2, EYmEventsO4 } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import styles from './BrandExtendedFilters.module.scss';

interface IBrandExtendedFiltersProps extends DrawerProps {}

export const BrandExtendedFilters: FC<IBrandExtendedFiltersProps> = ({ className, onClose, open, ...props }) => {
	const { t } = useTranslation();
	const {
		sourcesOptions,
		brandsOptions,
		sourcesIsFetching,
		brandsIsFetching,
		onFilterChange,
		getFilterValue,
		getALLFilterValues,
		clearFilters,
	} = useFilters();
	const {
		categoryOptions,
		trafficTypeOptions,
		tagsOptions,
		trans: { statUpdates, relationStatuses },
	} = useCommonSlice();

	useDisableBodyScroll(!!open);

	return (
		<Drawer
			{...props}
			open={open}
			onClose={onClose}
			width={450}
			title={t('Фильтры')}
			className={cn(className, styles.brandExtendedFilters)}>
			<Flex vertical gap={16}>
				<Form.Item label={t('Площадка')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.SOURCE, value)}
						onSelect={(value) =>
							sendYmEvent({
								event: EYmEvents.CLICK_FILTER,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.FILTER,
								o4: EYmEventsO4.ADSPACE,
								wi: value,
								isMarketing: false,
							})
						}
						value={sourcesIsFetching ? null : getALLFilterValues(EFilters.SOURCE)}
						options={sourcesOptions}
						loading={sourcesIsFetching}
						disabled={sourcesIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать площадку')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Рекламодатель')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.BRAND, value)}
						onSelect={(value) =>
							sendYmEvent({
								event: EYmEvents.CLICK_FILTER,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.FILTER,
								o4: EYmEventsO4.ADVERTISER,
								pi: value,
								isMarketing: false,
							})
						}
						value={brandsIsFetching ? null : getALLFilterValues(EFilters.BRAND)}
						options={brandsOptions}
						loading={brandsIsFetching}
						disabled={brandsIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать рекламодателя')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Категория')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
						onSelect={(value) =>
							sendYmEvent({
								event: EYmEvents.CLICK_FILTER,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.FILTER,
								o4: `${EYmEventsO4.CATEGORY};${value}`,
								isMarketing: false,
							})
						}
						value={getALLFilterValues(EFilters.CATEGORY)}
						options={categoryOptions}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать категорию')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Тип траффика')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.TRAFFIK, value)}
						onSelect={(value) =>
							sendYmEvent({
								event: EYmEvents.CLICK_FILTER,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.FILTER,
								o4: `${EYmEventsO4.TRAFFIK_TYPE};${value}`,
								isMarketing: false,
							})
						}
						value={getALLFilterValues(EFilters.TRAFFIK)}
						options={trafficTypeOptions}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать тип траффика')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Статус')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.STATUS, value)}
						value={getALLFilterValues(EFilters.STATUS)}
						options={Object.entries(relationStatuses)
							.filter(([key]) => key !== ESourceRelationStatuses.DISABLED && key !== ESourceRelationStatuses.NOT_JOINED)
							.map(([value, label]) => ({ label, value }))}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать статус')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Теги')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.TAG, value)}
						onSelect={(value) =>
							sendYmEvent({
								event: EYmEvents.CLICK_FILTER,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.FILTER,
								o4: `${EYmEventsO4.TAGS};${value}`,
								isMarketing: false,
							})
						}
						value={getALLFilterValues(EFilters.TAG)}
						options={tagsOptions}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать значение')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Частота обновления статистики')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.STATS, value)}
						onSelect={(value) =>
							sendYmEvent({
								event: EYmEvents.CLICK_FILTER,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.CATALOG],
								o2: EYmEventsO2.FILTER,
								o4: `${EYmEventsO4.UPDATE_STATISTIC};${value}`,
								isMarketing: false,
							})
						}
						value={getALLFilterValues(EFilters.STATS)}
						options={Object.keys(statUpdates).map((key) => ({
							label: statUpdates[key as keyof typeof statUpdates],
							value: key,
						}))}
						placeholder={t('Выбрать значение')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Checkbox
					onChange={(e) => {
						onFilterChange(EFilters.RECOMMENDED, e.target.checked ? 'true' : undefined);
					}}
					checked={getFilterValue(EFilters.RECOMMENDED) === 'true'}>
					{t('Только рекомендованные офферы')}
				</Checkbox>

				<Flex justify="space-between" className={styles.buttons}>
					<Button
						onClick={(e) => {
							clearFilters();
							onClose?.(e);
						}}>
						{t('Сбросить фильтры')}
					</Button>
					<Button type="primary" onClick={onClose}>
						{t('Применить')}
					</Button>
				</Flex>
			</Flex>
		</Drawer>
	);
};
